def transform(g):
    h,w=len(g),len(g[0])
    out=[r[:] for r in g]
    for i in range(h):
        if len(set(g[i]))==1:
            out[i]=[2]*w
    for j in range(w):
        col={g[i][j] for i in range(h)}
        if len(col)==1:
            for i in range(h): out[i][j]=2
    return out
